    function smoothstep(t) {
      return t * t * (3 - 2 * t);
    }

    function updateLadder(ladder, time) {
      const t = time;

      // Slide the stowed ladder out from beneath the path edge.
      if (t < 0.22) {
        const p = smoothstep(t / 0.22);
        ladder.outer.position.z = THREE.MathUtils.lerp(
          ladder.startZ,
          3.35,
          p
        );
      } else if (t < 0.58) {
