      updateDoor(time);

      let label;

      if (time < 1) {
        label = "Ladders stowed on ledge path";
      } else if (time < ladderPhases[0].end) {
        label = "I — raising first ladder";
      } else if (time < ladderPhases[1].end) {
        label = "II — raising second ladder";
      } else if (time < ladderPhases[2].end) {
        label = "III — raising third ladder";
      } else if (time < doorEnd) {
        label = "Counterweighted door — closing";
      } else {
        label = "Door sealed · sequence complete";
      }

      statusElement.textContent = label;
      progressFill.style.width = `${Math.min(time / sequenceDuration, 1) * 100}%`;
    }

    function replay() {
      elapsed = 0;
      paused = false;
      pauseButton.textContent = "Pause";
      updateScene(0);
    }

    pauseButton.addEventListener("click", () => {
      paused = !paused;
      pauseButton.textContent = paused ? "Resume" : "Pause";
    });

    document.getElementById("replay").addEventListener("click", replay);

    window.addEventListener("keydown", (event) => {
      if (event.key.toLowerCase() === "r") {
        replay();
      }

      if (event.code === "Space") {
        event.preventDefault();
        paused = !paused;
        pauseButton.textContent = paused ? "Resume" : "Pause";
